use std::num::ParseIntError;

fn twice(s: &str) -> Result<i32, ParseIntError> {
    let n = s.parse::<i32>()?;
    Ok(n * 2)
}

fn main() {
    println!("{:?}", twice("8"));
}

fn first_num(a: &str, b: &str) -> Result<i32, std::num::ParseIntError> {
    let x = a.parse::<i32>()?;
    println!("got x");
    let y = b.parse::<i32>()?;
    println!("got y");
    Ok(x + y)
}

fn main() {
    let r = first_num("1", "z");
    println!("{}", r.is_err());
}

