use std::error::Error;

fn check(n: i32) -> Result<i32, Box<dyn Error>> {
    if n < 0 {
        return Err("negative".into());
    }
    Ok(n)
}

fn main() {
    match check(-1) {
        Ok(n) => println!("ok {n}"),
        Err(e) => println!("err: {e}"),
    }
}

use std::num::ParseIntError;

enum E {
    Parse(ParseIntError),
    Neg,
}

impl From<ParseIntError> for E {
    fn from(e: ParseIntError) -> E {
        E::Parse(e)
    }
}

fn f(s: &str) -> Result<i32, E> {
    let n: i32 = s.parse()?;
    if n < 0 {
        return Err(E::Neg);
    }
    Ok(n)
}

fn main() {
    for s in ["4", "-4", "x"] {
        let tag = match f(s) {
            Ok(_) => "ok",
            Err(E::Neg) => "neg",
            Err(E::Parse(_)) => "parse",
        };
        print!("{tag} ");
    }
}
